# Сравнение с допуском и вывод у порога: число рядом с вердиктом
# показывается с таким числом значащих цифр, чтобы округлённое значение
# лежало по ту же сторону порога, что и точное (правило партий №2 и №3).
# pl() выбирает форму слова по показанной строке числа: у дроби — родительный
# падеж единственного числа («2,5 года»), у целого — обычные правила.
P_JS = r'''
function gt(a,b){return a>b*(1+1e-12);}
function lt(a,b){return a<b*(1-1e-12);}
function ge(a,b){return a>=b*(1-1e-12);}
function le(a,b){return a<=b*(1+1e-12);}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-12)return fmt(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if(x<lim?r<lim:r>lim)return fmt(x,p);}return fmt(x,12);}
function pl(s,one,few,many,frac){if(/[,·]/.test(s))return frac;var n=Math.abs(parseInt(s,10))%100,n1=n%10;if(n>10&&n<20)return many;if(n1===1)return one;if(n1>=2&&n1<=4)return few;return many;}
function yr(s){return s+' '+pl(s,'год','года','лет','года');}
'''

