short="t = H·(C/(I·H))^k против C/I, k по двум точкам паспорта, ватты на элемент",
title="Время работы ИБП от аккумулятора с учётом закона Пейкерта",
desc="Время работы ИБП от свинцово-кислотной батареи по закону Пейкерта t = H·(C/(I·H))^k в сравнении с простым C/I: показатель k из паспорта или по двум ёмкостям, мощность на элемент для таблицы разряда постоянной мощностью; для Li-ion — только C/I с объяснением почему.",
intro='Чем больше ток, тем меньше ампер-часов отдаёт свинцово-кислотная батарея: ёмкость в паспорте указана для долгого, обычно 20-часового разряда. Закон Пейкерта пересчитывает её на ток нагрузки ИБП. Расчёт по энергии без этой поправки делает <a href="vremya-raboty-akkumulyatora.html">калькулятор времени работы от аккумулятора</a> — здесь видно, насколько он оптимистичен при большом токе.',
kw="время работы ибп закон пейкерта показатель пейкерта аккумулятор ибп автономия ток разряда c20 ёмкость agm гель ватт на элемент таблица разряда постоянной мощностью",
fields=[
 dict(type="select", id="chem", label="Тип аккумулятора", opts=[
  ("lead","Свинцово-кислотный: AGM, гель, заливной"),
  ("li","Литий-ионный: LiFePO₄ и другие")], val="lead"),
 dict(id="p", label="Активная мощность нагрузки ИБП", unit="Вт", val="300"),
 dict(id="eta", label="КПД инвертора ИБП", unit="%", val="85", hint="По паспорту ИБП при вашей нагрузке"),
 dict(id="u", label="Номинальное напряжение батареи", unit="В", val="24", hint="Для свинцово-кислотной — кратно 2 В: 12, 24, 48 В"),
 dict(id="c", label="Ёмкость батареи C", unit="А·ч", val="100"),
 dict(id="h", label="Время разряда H, для которого указана ёмкость", unit="ч", val="20", hint="Обычно 20 часов (C20), бывает 10 часов (C10)"),
 dict(type="select", id="kmode", label="Показатель Пейкерта", opts=[
  ("set","Задать k"),
  ("two","Рассчитать по второй ёмкости из паспорта")], val="set"),
 dict(id="k", label="Показатель Пейкерта k", val="1,25", hint="Victron для свинцово-кислотных по умолчанию берёт 1,25, диапазон настройки монитора — 1,00–1,50. По Википедии (вторичный источник): AGM 1,05–1,15, гель 1,1–1,25, заливные 1,2–1,6"),
 dict(id="c2", label="Вторая ёмкость из паспорта", unit="А·ч", val="56", hint="Например, ёмкость при 2-, 5- или 1-часовом разряде"),
 dict(id="h2", label="Время разряда для второй ёмкости", unit="ч", val="2"),
],
js=P_JS + r'''
function sync(){var pb=S('chem')==='lead',two=pb&&S('kmode')==='two';hideF('h',!pb);hideF('kmode',!pb);hideF('k',!pb||two);hideF('c2',!two);hideF('h2',!two);}
function init(){$('chem').addEventListener('change',sync);$('kmode').addEventListener('change',sync);sync();}
function th(x,lim){return x>=1?fx(x,lim)+' ч':fx(x*60,lim*60)+' мин';}
function calc(){
var pb=S('chem')==='lead',two=pb&&S('kmode')==='two',p=P('p'),eta=P('eta'),u=P('u'),c=P('c'),h=pb?P('h'):1,k=NaN,c2=NaN,h2=NaN,nc=u/2;
if([p,eta,u,c,h].some(isNaN))return err(pb?'Заполните мощность нагрузки, КПД инвертора, напряжение, ёмкость и время разряда числами.':'Заполните мощность нагрузки, КПД инвертора, напряжение и ёмкость числами.');
if(p<=0||u<=0||c<=0||h<=0)return err(pb?'Мощность, напряжение, ёмкость и время разряда должны быть больше нуля.':'Мощность, напряжение и ёмкость должны быть больше нуля.');
if(eta<=0||eta>100)return err('КПД инвертора задаётся в процентах: больше 0 и не больше 100.');
if(pb&&(nc<1-1e-9||Math.abs(nc-Math.round(nc))>1e-9))return err('Номинальное напряжение свинцово-кислотной батареи кратно 2 В — по 2 В на элемент: 12, 24, 48 В и так далее.');
if(pb){nc=Math.round(nc);
 if(two){c2=P('c2');h2=P('h2');
  if(isNaN(c2)||isNaN(h2))return err('Введите вторую ёмкость из паспорта и время разряда для неё.');
  if(c2<=0||h2<=0)return err('Вторая ёмкость и время разряда должны быть больше нуля.');
  if(Math.abs(h2-h)<=1e-9*h)return err('Время разряда второй точки должно отличаться от H.');
  var i1=c/h,i2=c2/h2;
  if(Math.abs(i1-i2)<=1e-12*i1)return err('Токи разряда двух точек совпадают — показатель Пейкерта по ним не определить.');
  k=Math.log(h2/h)/Math.log(i1/i2);
  if(!(k>=1-1e-9&&k<=1.6+1e-9))return err('По двум точкам паспорта k = '+fmt(k)+' — вне диапазона 1…1,6, который источники дают для свинцово-кислотных АКБ. Проверьте, что меньшему времени разряда соответствует меньшая ёмкость.');}
 else{k=P('k');if(isNaN(k))return err('Введите показатель Пейкерта k.');
  if(k<1||k>1.6)return err('Показатель Пейкерта для свинцово-кислотных АКБ — от 1 до 1,6: Victron настраивает мониторы в диапазоне 1,00–1,50, по сводке Википедии у заливных бывает до 1,6.');}}
var i=p/(u*eta/100),t0=c/i,ir=c/h;
if(![i,t0].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
var r=pb?row('Ток батареи I = P / (U·η)',fx(i,ir)+' А')+row('Ток паспортного режима C/H',fx(ir,i)+' А'):row('Ток батареи I = P / (U·η)',fmt(i)+' А'),st,n;
r+=row('Без поправки на ток t = C/I',tf(t0*3600));
if(!pb){st='Оценка без поправки на ток: около '+tf(t0*3600)+' = C/I; закон Пейкерта для Li-ion не применяется';
 n='Закон Пейкерта выведен для свинцово-кислотных аккумуляторов. Для литий-ионных он работает лишь в узком диапазоне токов и температур, а у LiFePO₄ показатель в диапазоне 0–40 °C близок к 1 (Omar и Van den Bossche, 2013); Victron для литиевых батарей берёт 1,05, если поставщик не указал иное. Поэтому здесь только C/I. Ёмкость при вашем токе и допустимый ток разряда берите из паспорта батареи и ограничений BMS.';
 return out(r+row('Статус',st)+note(n));}
r+=row('Показатель Пейкерта k',fmt(k)+(two?' — по двум точкам паспорта':''));
if(lt(i,ir)){st='Оценка: около '+tf(t0*3600)+' = C/I; ток '+fx(i,ir)+' А меньше тока паспортного режима C/H = '+fx(ir,i)+' А, и формула Пейкерта дала бы больше паспортной ёмкости — в оценку она не берётся';
 r+=row('По Пейкерту','не применяется: ток ниже тока паспортного режима');}
else{var tp=h*Math.pow(c/(i*h),k),ce=i*tp;
 if(!isFinite(tp))return err('Значения вне диапазона надёжного расчёта.');
 if(two){var lo=Math.min(h,h2),hi=Math.max(h,h2),inr=ge(tp,lo)&&le(tp,hi),bd=inr?(tp-lo<hi-tp?lo:hi):(tp<lo?lo:hi),ts=th(tp,bd);
  st=inr?'Оценка по закону Пейкерта: около '+ts+' — между паспортными точками '+fmt(lo)+' и '+fmt(hi)+' ч'
   :'Оценка по закону Пейкерта с экстраполяцией: около '+ts+' — вне паспортных точек '+fmt(lo)+'…'+fmt(hi)+' ч; уточните по таблице разряда постоянной мощностью';}
 else{var ts=tf(tp*3600);st='Оценка по закону Пейкерта: около '+ts+' при k = '+fmt(k);}
 r+=row('По Пейкерту t = H·(C/(I·H))^k',ts)+row('Ёмкость, которую батарея отдаст при этом токе',fmt(ce)+' А·ч ('+fmt(100*ce/c)+' % от C)');}
r+=row('Мощность на элемент для таблицы производителя P / (η·n)',fmt(p/(eta/100)/nc)+' Вт на элемент, n = '+nc);
n='Закон Пейкерта — эмпирическая формула для свинцово-кислотных АКБ при постоянном токе и температуре (Doerffel и Abu Sharkh, 2006). ИБП разряжает батарею постоянной мощностью: напряжение по мере разряда падает, ток растёт, поэтому расчёт по номинальному напряжению оптимистичен. ';
n+='Точнее — по таблице разряда постоянной мощностью из паспорта батареи: найдите время, при котором элемент отдаёт не меньше '+fmt(p/(eta/100)/nc)+' Вт до конечного напряжения вашего ИБП (например, у CSB HR1234W — 34,3 Вт на элемент за 15 мин до 1,67 В на элемент при 25 °C); для таблиц «ватт на блок 12 В» умножьте на 6. ';
n+='Время — до конечного напряжения, для которого указана C; холод, старение и запас на конец срока службы его уменьшают.';
out(r+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">I = P / (U · η),&nbsp;&nbsp;t = H · (C / (I · H))<sup>k</sup>,&nbsp;&nbsp;без поправки: t = C / I<br>k по двум точкам паспорта: k = lg(H<sub>2</sub>/H<sub>1</sub>) / lg(I<sub>1</sub>/I<sub>2</sub>),&nbsp;&nbsp;I<sub>1</sub> = C<sub>1</sub>/H<sub>1</sub>,&nbsp;I<sub>2</sub> = C<sub>2</sub>/H<sub>2</sub><br>Мощность на элемент для таблицы производителя: P / (η · n),&nbsp;&nbsp;n = U / 2 В</div>
<p><b>Закон Пейкерта.</b> В 1897 году Вильгельм Пейкерт получил для свинцово-кислотных аккумуляторов эмпирическое соотношение I<sup>k</sup>·t = const: чем больше ток, тем меньше ампер-часов отдаёт батарея. Если ёмкость C указана для H-часового разряда, то есть для тока C/H, то при токе I время работы t = H·(C/(I·H))<sup>k</sup>. При k = 1 это обычное C/I; чем больше k, тем сильнее падает ёмкость с ростом тока. Батарея 100 А·ч (20-часовой разряд) с k = 1,2 при токе 10 А проработает 8,71 ч — отдаст 87 А·ч вместо 100.</p>
<p><b>Откуда взять k.</b> Лучше всего — рассчитать по двум ёмкостям из паспорта, как предлагает Victron в руководстве к мониторам батарей: 100 А·ч при 20-часовом разряде и 56 А·ч при 2-часовом дают k ≈ 1,34. Если второй точки нет, Victron по умолчанию берёт 1,25 для свинцово-кислотных, а диапазон настройки монитора — от 1,00 до 1,50. По сводке Википедии (вторичный источник) у AGM обычно 1,05–1,15, у гелевых 1,1–1,25, у заливных 1,2–1,6. Калькулятор принимает k от 1 до 1,6.</p>
<p><b>Где формула перестаёт работать.</b> Закон Пейкерта выведен для постоянного тока и постоянной температуры (Doerffel и Abu Sharkh, 2006). ИБП разряжает батарею постоянной мощностью: напряжение по мере разряда падает, ток растёт, поэтому расчёт по номинальному напряжению оптимистичен. При токе меньше тока паспортного режима C/H формула даёт ёмкость больше паспортной — это экстраполяция, и калькулятор тогда берёт в оценку C/I. Если k рассчитан по двум точкам, надёжна область между ними; за её пределами результат помечается как экстраполяция.</p>
<p><b>Таблицы производителя точнее.</b> Для ИБП производители батарей дают таблицы разряда постоянной мощностью: сколько ватт отдаёт элемент за 5, 10, 15, 30 минут до конечного напряжения, например 1,67 или 1,75 В на элемент. У CSB HR1234W — 34,3 Вт на элемент за 15 минут до 1,67 В на элемент при 25 °C. Производители ИБП подбирают батареи по мощности на элемент — нагрузке, делённой на КПД инвертора и число элементов. Калькулятор считает эту величину; время по ней и конечному напряжению вашего ИБП находят в таблице.</p>
<p><b>Li-ion.</b> Для литий-ионных аккумуляторов закон Пейкерта не применяется: Omar и Van den Bossche (2013) показали, что он описывает их лишь в узком диапазоне токов и температур, а у LiFePO₄ показатель в диапазоне 0–40 °C близок к 1. Victron для литиевых батарей берёт 1,05, если поставщик не указал иное. Поэтому для Li-ion калькулятор даёт только C/I, а допустимый ток и ёмкость задают паспорт и BMS.</p>""",
example="""<p>ИБП на 300 Вт с КПД инвертора 85 % работает от батареи 24 В 100 А·ч (C20, k = 1,25). Ток батареи 300 / (24 · 0,85) = <b>14,71 А</b> — почти втрое больше тока паспортного режима 5 А. Без поправки 100 / 14,71 = 6,8 ч, по Пейкерту 20 · (100 / (14,71 · 20))<sup>1,25</sup> = <b>5,19 ч</b>: батарея отдаст около 76,36 А·ч. Каждый из 12 элементов должен отдавать 300 / (0,85 · 12) = 29,41 Вт — по этой величине время ищут в таблице разряда постоянной мощностью.</p>
<p>Пример из руководства Victron: батарея 100 А·ч при 20-часовом разряде отдаёт 56 А·ч за 2 часа. По этим точкам k = lg 10 / lg 5,6 ≈ 1,337, и при токе 28 А калькулятор даёт ровно 2 ч — точка паспорта воспроизводится.</p>""",
