js=P_JS + r'''
function sync(){var pb=S('chem')==='lead';hideF('tref',!pb);hideF('temp',!pb);}
function init(){$('chem').addEventListener('change',sync);sync();}
function calc(){
var pb=S('chem')==='lead',r=P('r'),s0=P('s0'),th=P('th'),m=P('m'),tr=NaN,tt=NaN,f=1;
if([r,s0,th,m].some(isNaN))return err('Заполните саморазряд, начальный заряд, порог подзаряда и срок хранения числами.');
if(r<=0||r>=100)return err('Саморазряд задаётся в процентах в месяц: больше 0 и меньше 100.');
if(s0<=0||s0>100)return err('Начальный заряд — больше 0 и не больше 100 %.');
if(th<=0||th>=100)return err('Порог подзаряда — больше 0 и меньше 100 %.');
if(m<=0)return err('Срок хранения должен быть больше нуля.');
if(pb){tr=P('tref');tt=P('temp');
 if(isNaN(tr)||isNaN(tt))return err('Введите температуру, при которой в паспорте указан саморазряд, и температуру хранения.');
 if(tr<15||tr>30)return err('Саморазряд в паспортах указывают при 20–25 °C; калькулятор принимает температуру паспорта от 15 до 30 °C.');
 if(tt>40)return err('Выше 40 °C удвоение саморазряда на каждые 10 °C в найденных источниках не подтверждено — такие температуры калькулятор не считает.');
 if(tt<-40)return err('Температура хранения ниже −40 °C — вне области калькулятора.');
 if(gt(tt,tr))f=Math.pow(2,(tt-tr)/10);}
var rt=r*f;
if(rt>=100)return err('С поправкой на температуру саморазряд получается '+fmt(rt)+' % в месяц — вне модели.');
var sl=Math.max(0,s0-rt*m),tl=(s0-th)/rt,q=1-rt/100,se=s0*Math.pow(q,m),te=Math.log(th/s0)/Math.log(q),t0=s0/rt;
var h='';
if(pb)h+=row('Поправка на температуру 2^((T − Tп)/10)',f>1?'× '+fmt(f):'не применяется: хранение не теплее паспортной температуры');
h+=row('Саморазряд при хранении r',fmt(rt)+' % в месяц');
var st;
if(!gt(s0,th)){st='Подзарядите перед хранением: начальный заряд '+fx(s0,th)+' % не выше порога '+fx(th,s0)+' %';
 h+=row('Заряд через '+fmt(m)+' мес. — линейно',fmt(sl)+' %');}
else{h+=row('Заряд через '+fmt(m)+' мес. — линейно, как у Panasonic',fx(sl,th)+' %'+(sl<=0?' — полный разряд через '+fmt(t0)+' мес.':''))+
 row('Время до порога подзаряда '+fmt(th)+' %',fx(tl,m)+' мес.')+
 row('Для сравнения: экспоненциально (1 − r)^t',fmt(se)+' % через '+fmt(m)+' мес., порог — через '+fmt(te)+' мес.');
 st=gt(tl,m)?'Оценка: через '+fmt(m)+' мес. заряд около '+fx(sl,th)+' % — выше порога '+fmt(th)+' %; порог — примерно через '+fx(tl,m)+' мес.'
  :'Подзаряд нужен не позже чем через '+fx(tl,m)+' мес.: к концу хранения ('+fx(m,tl)+' мес.) заряд опустится до '+fx(sl,th)+' % при пороге '+fmt(th)+' %';}
var n='Линейная модель: r — процент номинальной ёмкости в месяц, поэтому заряд убывает на одну и ту же величину каждый месяц; так саморазряд оценивает Panasonic: [5 %/мес.] × число месяцев. Экспоненциальная модель теряет долю r от остатка и даёт больший остаток — она показана только для сравнения, вывод — по линейной. ';
if(pb){n+='Для свинцово-кислотных VRLA саморазряд примерно удваивается на каждые 10 °C (Victron, Panasonic; у EnerSys SBS XC — 1,25 % при 20 °C и 5 % при 40 °C). ';
 if(f===1)n+='Ниже паспортной температуры саморазряд меньше, но поправка не делается — оценка с запасом. ';
 n+='Производители задают и порог по напряжению: EnerSys — подзаряд через 6 мес. при 20 °C или когда напряжение разомкнутой цепи приближается к 2,10 В на элемент, что наступит раньше; Yuasa NP — после 6 мес. хранения или ниже 2,1 В на элемент. Проверяйте напряжением: расчёт по r — оценка.';}
else n+='Поправка на температуру не применяется: удвоение на каждые 10 °C в найденных источниках подтверждено только для свинцово-кислотных VRLA. Введите r для вашей температуры хранения. У Li-ion, по Battery University, в первые сутки после заряда уходит около 5 % — модель эту потерю не описывает.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">SoC(t) = SoC₀ − r<sub>T</sub> · t,&nbsp;&nbsp;t<sub>порог</sub> = (SoC₀ − SoC<sub>порог</sub>) / r<sub>T</sub><br>Свинцово-кислотные VRLA: r<sub>T</sub> = r · 2<sup>(T − T<sub>п</sub>)/10</sup> при T выше T<sub>п</sub>, до 40 °C<br>Для сравнения: SoC(t) = SoC₀ · (1 − r<sub>T</sub>)<sup>t</sup></div>
<p><b>Саморазряд в паспорте</b> задают в процентах номинальной ёмкости в месяц при определённой температуре: у Yuasa NP — около 3 % в месяц при 20 °C, у Victron GEL и AGM — меньше 2 % при 20 °C, у EnerSys SBS XC — 1,25 % при 20 °C. У литий-ионных, по сводке Battery University (вторичный источник), — 1–2 % в месяц после первых суток, в которые уходит около 5 %, плюс до 3 % в месяц на схему защиты; у никелевых — 10–15 % в месяц. Это ориентиры: вводите значение из паспорта своего аккумулятора. С возрастом саморазряд растёт.</p>
<p><b>Почему линейно.</b> Раз r — процент номинальной ёмкости, заряд убывает на одну и ту же величину каждый месяц. Так саморазряд и оценивает Panasonic в справочнике по VRLA: при хранении ниже 20 °C принимать [5 %/мес.] × число месяцев. Экспоненциальная модель, в которой каждый месяц теряется доля r от остатка, даёт остаток больше линейного и порог позже — калькулятор показывает её только для сравнения, вывод делается по линейной.</p>
<p><b>Температура.</b> Для свинцово-кислотных VRLA саморазряд примерно удваивается на каждые 10 °C: так пишут Victron и Panasonic, и так устроена таблица EnerSys для SBS XC — 1,25 % в месяц при 20 °C, 1,76 % при 25 °C, 2,5 % при 30 °C и 5 % при 40 °C. Калькулятор применяет удвоение от температуры, при которой в паспорте указан r, до 40 °C. Ниже паспортной температуры саморазряд меньше, но поправка не делается — оценка с запасом. Для других химий удвоение в найденных источниках не подтверждено: вводите r для своей температуры хранения.</p>
<p><b>Порог подзаряда.</b> Производители свинцово-кислотных АКБ задают его сроком и напряжением разомкнутой цепи: EnerSys для PowerSafe PV Bloc — подзаряд через 6 месяцев при 20 °C или когда напряжение приближается к 2,10 В на элемент, что наступит раньше; Yuasa для NP — после 6 месяцев хранения или при напряжении ниже 2,1 В на элемент. По таблице Battery University 2,10 В на элемент — это примерно 90 % заряда, 2,07 В — около 70 %. Порог в процентах задаёте вы; перед подзарядом проверьте напряжение.</p>""",
example="""<p>AGM с саморазрядом 3 % в месяц при 20 °C хранят полгода в гараже при 30 °C. Поправка 2<sup>(30 − 20)/10</sup> = 2, саморазряд 6 % в месяц. Через 6 месяцев останется 100 − 6 · 6 = <b>64 %</b>, а порог 90 % наступит уже через 10 / 6 ≈ <b>1,667 месяца</b> — подзаряжать нужно задолго до конца хранения. Экспоненциальная модель дала бы 68,99 % и 1,703 месяца.</p>
<p>Тот же аккумулятор при 20 °C: 3 % в месяц, через 6 месяцев — 82 %, порог 90 % — через 3,333 месяца. При 40 °C саморазряд вырос бы вчетверо, до 12 % в месяц.</p>""",
